"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { apiFetch } from "@/app/dashboard/_lib/api";
import { getRolePreset, normalizeRole } from "@/lib/window-layout-presets";

/**
 * Per-module layout preferences.
 * Extend these types as needed when new modules adopt the layout system.
 */
export type PanelId = string;

export type ModuleLayoutPrefs = {
  /** Sidebar width as a percentage [10, 80] */
  sidebarPercent?: number;
  /** Generic split ratio [10, 90] for docked panes */
  splitPercent?: number;
  /** Which panels are currently visible (by panel id) */
  visiblePanels?: PanelId[];
  /** Pane arrangement axis */
  layoutMode?: "horizontal" | "vertical";
  /** Preferred position for the primary panel */
  primaryPanelPosition?: "left" | "right" | "top" | "bottom";
};

export type UiPreferences = {
  inbox?: ModuleLayoutPrefs;
  recovery?: ModuleLayoutPrefs;
  [module: string]: ModuleLayoutPrefs | undefined;
};

const STORAGE_KEY = "hbx:ui-prefs";

function readFromStorage(): UiPreferences {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as UiPreferences) : {};
  } catch {
    return {};
  }
}

function writeToStorage(prefs: UiPreferences) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
  } catch {
    // ignore
  }
}

/**
 * Hook for reading and writing UI layout preferences.
 * Reads from localStorage immediately, syncs with backend asynchronously.
 * Writes to localStorage instantly and debounces backend sync (1.5 s).
 */
export function useUiPreferences() {
  const [prefs, setPrefs] = useState<UiPreferences>(() => readFromStorage());
  const syncTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const loadedRef = useRef(false);

  // Load from backend once on mount
  useEffect(() => {
    if (loadedRef.current) return;
    loadedRef.current = true;

    apiFetch<UiPreferences>("/users/me/ui-preferences")
      .then((data) => {
        if (!data || typeof data !== "object" || Array.isArray(data)) return;
        setPrefs((prev) => {
          // Backend wins for non-empty values; localStorage wins if backend is empty
          const merged: UiPreferences = { ...prev };
          for (const key of Object.keys(data)) {
            if (data[key] !== undefined) merged[key] = data[key];
          }
          writeToStorage(merged);
          return merged;
        });
      })
      .catch(() => {
        // non-fatal: keep localStorage values
      });
  }, []);

  // Listen for global reset event
  useEffect(() => {
    function handleReset() {
      setPrefs({});
      writeToStorage({});
    }
    window.addEventListener("hbx-reset-layout", handleReset);
    return () => window.removeEventListener("hbx-reset-layout", handleReset);
  }, []);

  /**
   * Partial update for a specific module's layout prefs.
   * Instantly commits to localStorage and debounces backend sync.
   */
  const updateModule = useCallback((module: string, patch: Partial<ModuleLayoutPrefs>) => {
    setPrefs((prev) => {
      const next: UiPreferences = {
        ...prev,
        [module]: { ...(prev[module] ?? {}), ...patch },
      };
      writeToStorage(next);

      // Debounced backend sync
      if (syncTimerRef.current) clearTimeout(syncTimerRef.current);
      syncTimerRef.current = setTimeout(() => {
        apiFetch("/users/me/ui-preferences", {
          method: "PATCH",
          body: JSON.stringify({ [module]: next[module] }),
        }).catch(() => {
          // non-fatal
        });
      }, 1500);

      return next;
    });
  }, []);

  /**
   * Reset all layout preferences to defaults.
   * Fires a global event so all mounted components react.
   */
  const resetAll = useCallback(() => {
    setPrefs({});
    writeToStorage({});
    if (syncTimerRef.current) clearTimeout(syncTimerRef.current);
    apiFetch("/users/me/ui-preferences/reset", { method: "PATCH" }).catch(() => {});
    window.dispatchEvent(new CustomEvent("hbx-reset-layout"));
  }, []);

  const getModulePrefs = useCallback(
    (module: string, roleRaw?: string | null): ModuleLayoutPrefs => {
      const preset = getRolePreset(module, roleRaw);
      const saved = prefs[module] ?? {};
      return {
        sidebarPercent: saved.sidebarPercent ?? preset.sidebarPercent,
        splitPercent: saved.splitPercent ?? preset.splitPercent ?? saved.sidebarPercent ?? preset.sidebarPercent,
        visiblePanels:
          saved.visiblePanels && saved.visiblePanels.length > 0
            ? saved.visiblePanels
            : preset.visiblePanels,
        layoutMode: saved.layoutMode ?? preset.layoutMode,
        primaryPanelPosition: saved.primaryPanelPosition ?? preset.primaryPanelPosition,
      };
    },
    [prefs],
  );

  const applyRolePreset = useCallback(
    (module: string, roleRaw?: string | null) => {
      const role = normalizeRole(roleRaw);
      const preset = getRolePreset(module, role);
      updateModule(module, {
        visiblePanels: preset.visiblePanels,
        sidebarPercent: preset.sidebarPercent,
        splitPercent: preset.splitPercent ?? preset.sidebarPercent,
        layoutMode: preset.layoutMode,
        primaryPanelPosition: preset.primaryPanelPosition,
      });
    },
    [updateModule],
  );

  return { prefs, updateModule, resetAll, getModulePrefs, applyRolePreset };
}
