export function normalizeRole(rawRole: string | null | undefined): WindowRole {
  const role = String(rawRole || "").trim().toUpperCase();
  if (role === "ADMIN") return "ADMIN";
  if (role === "GERENTE") return "GERENTE";
  return "USER";
}

export function getRolePreset(module: string, roleRaw: string | null | undefined): ModuleLayoutPreset {
  const role = normalizeRole(roleRaw);
  const byModule = WINDOW_ROLE_PRESETS[module];
  if (!byModule) {
    return { visiblePanels: [] };
  }
  return byModule[role] || byModule.USER;
}
